//! Experimental fd-to-fd export. The child is single-threaded and never changes the parent's cwd.
use std::{ffi::{CStr,CString,OsStr},fs,io::{self,Read,Seek,Write},os::{fd::{AsRawFd,FromRawFd},unix::{ffi::OsStrExt,process::CommandExt}},path::Path,process::{Command,Stdio}};
